begin;
create function public.import_report(p_original text,p_replace boolean default false) returns integer language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();r jsonb;s public.sessions;k text;v jsonb;n integer;total integer;used integer;points integer;begin
if u is null then raise exception 'Autenticação necessária';end if;
if octet_length(p_original)>262144 then raise exception 'JSON excede limite';end if;r:=p_original::jsonb;
if jsonb_typeof(r)<>'object' or r->'schema_version' is distinct from '1'::jsonb or r->>'assessment_source' is distinct from 'chatgpt_self_reported' then raise exception 'Contrato incompatível';end if;
perform pg_advisory_xact_lock(hashtextextended(u::text,0));
select * into s from public.sessions where id=(r->>'session_id')::uuid and user_id=u for update;
if not found or s.ended_at is null or s.mode='explanation' then raise exception 'Sessão encerrada de conversação necessária';end if;
if r->>'script_id' is distinct from s.script_id::text or r->>'language' is distinct from s.language or r->>'level' is distinct from s.level or r->>'scenario' is distinct from s.scenario or not (r?'script_id') then raise exception 'Relatório não corresponde à sessão';end if;
if jsonb_typeof(r->'completed') is distinct from 'boolean' or jsonb_typeof(r->'metrics') is distinct from 'object' or jsonb_typeof(r->'evidence') is distinct from 'object' then raise exception 'Campos obrigatórios inválidos';end if;
foreach k in array array['grammar','vocabulary','listening_comprehension','contextual_appropriateness','perceived_fluency','pronunciation','overall_score'] loop v:=case when k='overall_score' then r->k else r->'metrics'->k end;if v is null or jsonb_typeof(v) not in ('number','null') then raise exception 'Métrica inválida: %',k;end if;if jsonb_typeof(v)='number' and (v::numeric<0 or v::numeric>100) then raise exception 'Nota fora do intervalo';end if;end loop;
foreach k in array array['corrections','strengths','difficulties','recommendations','limitations'] loop if jsonb_typeof(r->k) is distinct from 'array' or jsonb_array_length(r->k)>100 then raise exception 'Lista inválida: %',k;end if;end loop;
if jsonb_typeof(r->'evidence'->'assessed_turns') is distinct from 'number' or jsonb_typeof(r->'evidence'->'total_turns') is distinct from 'number' or jsonb_typeof(r->'evidence'->'acoustic_evidence') is distinct from 'boolean' or jsonb_typeof(r->'evidence'->'notes') is distinct from 'string' then raise exception 'Evidência inválida';end if;
foreach k in array array['strengths','difficulties','recommendations','limitations'] loop
 if jsonb_array_length(r->k)>50 or exists(select 1 from jsonb_array_elements(r->k) e where jsonb_typeof(e)<>'string' or length(trim(e#>>'{}')) not between 1 and 4000) then raise exception 'Texto inválido: %',k;end if;end loop;
 if exists(select 1 from jsonb_array_elements(r->'corrections') e where jsonb_typeof(e)<>'object' or jsonb_typeof(e->'original') is distinct from 'string' or jsonb_typeof(e->'corrected') is distinct from 'string' or jsonb_typeof(e->'explanation_pt') is distinct from 'string' or length(trim(e->>'original')) not between 1 and 4000 or length(trim(e->>'corrected')) not between 1 and 4000 or length(trim(e->>'explanation_pt')) not between 1 and 4000) then raise exception 'Correções inválidas';end if;
 if length(r->'evidence'->>'notes')>4000 or (r->'evidence'->>'assessed_turns')::numeric<>trunc((r->'evidence'->>'assessed_turns')::numeric) or (r->'evidence'->>'total_turns')::numeric<>trunc((r->'evidence'->>'total_turns')::numeric) then raise exception 'Evidência inválida';end if;
 n:=(r->'evidence'->>'assessed_turns')::int;total:=(r->'evidence'->>'total_turns')::int;if n<0 or total<n or total>10000 then raise exception 'Cobertura inválida';end if;
if r->'metrics'->'pronunciation'<>'null'::jsonb and (r->'evidence'->>'acoustic_evidence'<>'true' or length(trim(r->'evidence'->>'notes'))=0) then raise exception 'Pronúncia sem evidência';end if;
if n=0 and (r->'overall_score'<>'null'::jsonb or exists(select 1 from jsonb_each(r->'metrics') where value<>'null'::jsonb)) then raise exception 'Notas sem turnos avaliados';end if;
if (r->>'completed'='false' or n<total) and jsonb_array_length(r->'limitations')=0 then raise exception 'Relatório parcial requer limitações';end if;
if exists(select 1 from public.reports where session_id=s.id) then if not p_replace then raise exception 'Relatório duplicado; use revisão explícita';end if;delete from public.reports where session_id=s.id and user_id=u;end if;
select coalesce(sum(x.points),0) into used from public.xp_events x where x.user_id=u and x.local_day=s.local_day;
points:=case when n=0 or s.active_seconds=0 then 0 else greatest(0,least(200-used,100,(s.active_seconds/60)*5+n*2)) end;
insert into public.reports(session_id,user_id,payload,original) values(s.id,u,r,p_original);insert into public.xp_events values(s.id,u,points,s.local_day);perform public.refresh_achievements(u);return points;end $$;
create function public.delete_report(p_session uuid) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null then raise exception 'Autenticação necessária';end if;perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0));delete from public.reports where session_id=p_session and user_id=auth.uid();perform public.refresh_achievements(auth.uid());end $$;
create function public.public_ranking(p_language text,p_from date) returns table(nickname text,points bigint,position bigint,is_me boolean) language sql stable security definer set search_path='' as $$ select p.nickname,sum(x.points),rank() over(order by sum(x.points) desc),p.id=auth.uid() from public.xp_events x join public.profiles p on p.id=x.user_id join public.sessions s on s.id=x.session_id where auth.uid() is not null and p.ranking_opt_in and (p_language='' or s.language=p_language) and (p_from is null or x.local_day>=p_from) group by p.id,p.nickname order by sum(x.points) desc,p.nickname limit 100 $$;
create function public.delete_my_data() returns void language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid();begin if u is null then raise exception 'Autenticação necessária';end if;perform pg_advisory_xact_lock(hashtextextended(u::text,0));delete from public.sessions where user_id=u;delete from public.scripts where user_id=u;delete from public.preferences where user_id=u;delete from public.profiles where id=u;delete from public.user_achievements where user_id=u;delete from public.mutation_receipts where user_id=u;end $$;
revoke all on function public.import_report(text,boolean),public.delete_report(uuid),public.public_ranking(text,date),public.delete_my_data() from public,anon;
grant execute on function public.import_report(text,boolean),public.delete_report(uuid),public.public_ranking(text,date),public.delete_my_data() to authenticated;
commit;
